const TTL_SEC = 86400;
const rows = $input.all().map((i) => i.json);
const cancelledSlot = $('Edit Fields').item.json.body.payload.startTime;
const bookingUrl = 'https://sites.google.com/view/portail-temara-mall/accueil';

function normPhone(p) {
  return String(p ?? '').replace(/[\s\-\(\)\.]/g, '').trim();
}

rows.sort((a, b) => {
  const pa = Number(a['Priorité'] ?? a['Priorite'] ?? a['Priority'] ?? 999);
  const pb = Number(b['Priorité'] ?? b['Priorite'] ?? b['Priority'] ?? 999);
  return pa - pb;
});

const top3 = rows.slice(0, 3);
const batchId = `wl-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;

async function baserowCreateBroadcastRow(payload) {
  const base = String($env['BASEROW_API_URL'] ?? 'https://api.baserow.io').replace(/\/+$/, '');
  const token = String($env['BASEROW_API_TOKEN'] ?? '').trim();
  const tableId = String($env['BASEROW_WAITLIST_BROADCAST_TABLE_ID'] ?? '').trim();
  if (!token) throw new Error('CRITICAL: BASEROW_API_TOKEN missing from environment');
  if (!tableId) throw new Error('CRITICAL: BASEROW_WAITLIST_BROADCAST_TABLE_ID missing from environment');

  const res = await fetch(`${base}/api/database/rows/table/${tableId}/?user_field_names=true`, {
    method: 'POST',
    headers: {
      Authorization: `Token ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(payload),
  });
  if (!res.ok) {
    const body = await res.text();
    throw new Error(`BASEROW_CREATE_FAIL: ${res.status} ${body.slice(0, 200)}`);
  }
  return res.json();
}

return (async () => {
  const out = [];
  for (const r of top3) {
    const nom = r['Nom'] ?? r['Patient (Nom Complet)'] ?? 'Patient';
    const phone = r['Téléphone (WhatsApp)'] ?? r['Telephone'] ?? r['Phone'] ?? '';
    const phoneNorm = normPhone(phone);
    if (!phoneNorm) continue;

    const dedupKey = `waitlist:notified:${phoneNorm}`;
    const lock = await redisSetNx(dedupKey, TTL_SEC);
    if (!lock.ok) {
      throw new Error(`REDIS_FAIL: ${lock.redisError}`);
    }
    if (!lock.acquired) {
      continue;
    }

    await baserowCreateBroadcastRow({
      Slot: cancelledSlot,
      'Patient Name': nom,
      Phone: phone,
      Status: 'Notified',
      'Broadcast Batch': batchId,
      'Booked By Phone': '',
    });

    out.push({
      json: {
        Nom: nom,
        Phone: phone,
        Booking_URL: bookingUrl,
        cancelledSlot,
        broadcastBatch: batchId,
      },
    });
  }
  return out;
})();

// Slot Filled Cleanup: Baserow-backed waitlist cascade (no in-memory state)
const startTime = $('Edit Fields').item.json.body.payload.startTime;
const bookerPhone = ($('Edit Fields').item.json.Clean_Phone ?? '').toString().trim();
const portalUrl = 'https://sites.google.com/view/portail-temara-mall/accueil';

function normPhone(p) {
  return String(p ?? '').replace(/[\s\-\(\)\.]/g, '').trim();
}

async function baserowListNotifiedForSlot(slot) {
  const base = String($env['BASEROW_API_URL'] ?? 'https://api.baserow.io').replace(/\/+$/, '');
  const token = String($env['BASEROW_API_TOKEN'] ?? '').trim();
  const tableId = String($env['BASEROW_WAITLIST_BROADCAST_TABLE_ID'] ?? '').trim();
  if (!token || !tableId) throw new Error('CRITICAL: Baserow waitlist broadcast env not configured');

  const filters = encodeURIComponent(JSON.stringify({
    filter_type: 'AND',
    filters: [
      { field: 'Slot', type: 'equal', value: slot },
      { field: 'Status', type: 'equal', value: 'Notified' },
    ],
  }));

  const res = await fetch(`${base}/api/database/rows/table/${tableId}/?user_field_names=true&filters=${filters}`, {
    method: 'GET',
    headers: { Authorization: `Token ${token}` },
  });
  if (!res.ok) throw new Error(`BASEROW_LIST_FAIL: ${res.status}`);
  const data = await res.json();
  return data.results ?? [];
}

async function baserowUpdateRow(rowId, fields) {
  const base = String($env['BASEROW_API_URL'] ?? 'https://api.baserow.io').replace(/\/+$/, '');
  const token = String($env['BASEROW_API_TOKEN'] ?? '').trim();
  const tableId = String($env['BASEROW_WAITLIST_BROADCAST_TABLE_ID'] ?? '').trim();
  const res = await fetch(`${base}/api/database/rows/table/${tableId}/${rowId}/?user_field_names=true`, {
    method: 'PATCH',
    headers: {
      Authorization: `Token ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(fields),
  });
  if (!res.ok) throw new Error(`BASEROW_UPDATE_FAIL: ${res.status}`);
  return res.json();
}

return (async () => {
  const rows = await baserowListNotifiedForSlot(startTime);
  if (!rows.length) return [];

  const bookerNorm = normPhone(bookerPhone);
  const bookerRow = rows.find((r) => normPhone(r.Phone) === bookerNorm);
  if (!bookerRow) return [];

  const batchId = bookerRow['Broadcast Batch'];
  await baserowUpdateRow(bookerRow.id, {
    Status: 'Booked',
    'Booked By Phone': bookerPhone,
  });

  const remaining = rows
    .filter((r) => r['Broadcast Batch'] === batchId)
    .filter((r) => normPhone(r.Phone) !== bookerNorm)
    .slice(0, 2);

  return remaining.map((p) => ({
    json: {
      Nom: p['Patient Name'] ?? 'Patient',
      Phone: p.Phone ?? '',
      Portal_URL: portalUrl,
    },
  }));
})();

// Parse Twilio delivery status callback payload
const body = $input.first().json.body ?? $input.first().json;
const messageSid = (body.MessageSid ?? body.messageSid ?? '').toString().trim();
const messageStatus = (body.MessageStatus ?? body.messageStatus ?? body.SmsStatus ?? 'unknown').toString().trim();
return [{ json: { messageSid, messageStatus } }];

// ── GATE: Cal.com webhook secret (timing-safe header check) ─────────────────
const crypto = require('crypto');

function timingSafeEqualStrings(a, b) {
  const sa = String(a ?? '');
  const sb = String(b ?? '');
  const ba = Buffer.from(sa, 'utf8');
  const bb = Buffer.from(sb, 'utf8');
  if (ba.length !== bb.length) return false;
  return crypto.timingSafeEqual(ba, bb);
}

function readHeader(h, name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(h ?? {})) {
    if (key && key.toLowerCase() === target) return String(value ?? '').trim();
  }
  return '';
}

const item = $input.first().json ?? {};
const headers = item.headers ?? {};
const expected = String($env['CAL_WEBHOOK_SECRET'] ?? '').trim();

if (!expected) {
  throw new Error('AUTH_FAIL: CAL_WEBHOOK_SECRET is not configured');
}

const incoming = readHeader(headers, 'x-cal-secret-256')
  || readHeader(headers, 'x-cal-signature-256')
  || readHeader(headers, 'x-agency-auth');

if (!incoming || !timingSafeEqualStrings(incoming, expected)) {
  throw new Error('AUTH_FAIL: Invalid or missing Cal.com webhook secret');
}

return $input.all();

// ── Concierge auth rejection (401) ───────────────────────────────────────────
const err = $input.first()?.json ?? {};
const errMsg = (err.message ?? err.error ?? 'Unauthorized').toString();
const isAuth = errMsg.startsWith('AUTH_FAIL') || errMsg.startsWith('SIG_FAIL');

return [{
  json: {
    httpStatus: isAuth ? 401 : 503,
    body: {
      ok: false,
      error: isAuth ? 'Unauthorized' : 'Service Unavailable',
    },
  },
}];

// ── GATE: Twilio SMS status callback signature validation ───────────────────
const crypto = require('crypto');

function timingSafeEqualStrings(a, b) {
  const sa = String(a ?? '');
  const sb = String(b ?? '');
  const ba = Buffer.from(sa, 'utf8');
  const bb = Buffer.from(sb, 'utf8');
  if (ba.length !== bb.length) return false;
  return crypto.timingSafeEqual(ba, bb);
}

function readTwilioSignature(headers) {
  for (const [key, value] of Object.entries(headers ?? {})) {
    if (key && key.toLowerCase() === 'x-twilio-signature') {
      return String(value ?? '').trim();
    }
  }
  return '';
}

function buildTwilioValidationUrl(webhookBase, path, query) {
  const base = String(webhookBase ?? '').replace(/\/+$/, '');
  const p = String(path ?? '').replace(/^\//, '');
  let url = `${base}/${p}`;
  const q = String(query ?? '').trim();
  if (q) url += (q.startsWith('?') ? q : `?${q}`);
  return url;
}

function computeTwilioSignature(authToken, url, params) {
  const sortedKeys = Object.keys(params ?? {}).sort();
  let data = url;
  for (const k of sortedKeys) {
    data += k + String(params[k] ?? '');
  }
  return crypto.createHmac('sha1', authToken).update(data, 'utf8').digest('base64');
}

const item = $input.first().json ?? {};
const headers = item.headers ?? {};
const body = item.body ?? {};
const query = item.query ?? {};

const authToken = String($env['N8N_TWILIO_AUTH_TOKEN'] ?? '').trim();
if (!authToken) {
  throw new Error('AUTH_FAIL: N8N_TWILIO_AUTH_TOKEN is not configured');
}

const webhookBase = String($env['N8N_WEBHOOK_BASE_URL'] ?? '').trim();
if (!webhookBase) {
  throw new Error('AUTH_FAIL: N8N_WEBHOOK_BASE_URL is not configured');
}

const twilioSig = readTwilioSignature(headers);
if (!twilioSig) {
  throw new Error('AUTH_FAIL: Missing X-Twilio-Signature header');
}

const validationUrl = buildTwilioValidationUrl(webhookBase, 'webhook/twilio-sms-status', query);
const expectedSig = computeTwilioSignature(authToken, validationUrl, body);

if (!timingSafeEqualStrings(twilioSig, expectedSig)) {
  throw new Error('AUTH_FAIL: Invalid Twilio signature');
}

return $input.all();

// ── Concierge auth rejection (401) ───────────────────────────────────────────
const err = $input.first()?.json ?? {};
const errMsg = (err.message ?? err.error ?? 'Unauthorized').toString();
const isAuth = errMsg.startsWith('AUTH_FAIL') || errMsg.startsWith('SIG_FAIL');

return [{
  json: {
    httpStatus: isAuth ? 401 : 503,
    body: {
      ok: false,
      error: isAuth ? 'Unauthorized' : 'Service Unavailable',
    },
  },
}];

