const TTL_SEC = 86400;

return (async () => {
  const items = $input.all();
  const root = items[0]?.json ?? {};
  const body = root.body ?? root;
  const messageSid = String(body.MessageSid ?? body.messageSid ?? '').trim();
  if (!messageSid) {
    return [{ json: { ...root, _lockDuplicate: false, _lockRedisError: null } }];
  }

  const lockKey = `lock:twilio-sms:${messageSid}`;
  const lock = await redisSetNx(lockKey, TTL_SEC);

  if (!lock.ok) {
    return [{
      json: {
        ...root,
        _lockDuplicate: false,
        _lockRedisError: lock.redisError,
        _lockKey: lockKey,
      },
    }];
  }
  if (!lock.acquired) {
    return [{
      json: {
        ...root,
        _lockDuplicate: true,
        _lockRedisError: null,
        _lockKey: lockKey,
      },
    }];
  }
  return [{ json: { ...root, _lockDuplicate: false, _lockRedisError: null, _lockKey: lockKey } }];
})();
